BEGIN;

CREATE TEMP TABLE editorial_batch_003 (
  id text,
  summary_es text NOT NULL,
  essay_es text NOT NULL,
  summary_en text NOT NULL,
  essay_en text NOT NULL
);


UPDATE editorial_batch_003 SET id='cmsvvxiba00il85sjnb7w51u3' WHERE id='cmsvvxirx00sd85sjicyi8d4w' AND summary_es LIKE 'Henri Cartier-Bresson%';

UPDATE "Entity" e SET summary=b.summary_es, content=b.essay_es FROM editorial_batch_003 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET "shortDescription"=b.summary_es, essay=b.essay_es, excerpt=b.summary_es FROM editorial_batch_003 b WHERE t."entityId"=b.id AND t.locale='es';
UPDATE "Entity" e SET content=replace(e.content,chr(92)||'n',chr(10)) FROM editorial_batch_003 b WHERE e.id=b.id;
UPDATE "EntityTranslation" t SET essay=replace(t.essay,chr(92)||'n',chr(10)) WHERE t."entityId" IN (SELECT id FROM editorial_batch_003) AND t.locale IN ('es','en');

-- Restore the Batch 001 artwork that temporarily shared an artist lookup id.
UPDATE "Entity" SET summary='Olympia, pintada por Édouard Manet en 1863, es un óleo sobre lienzo relacionado con el cuerpo, el deseo, el desnudo, la mirada y el género.', content='## Cuerpo y mirada' || chr(10) || chr(10) || '[[olympia|Olympia]] fue pintada en 1863 con óleo sobre lienzo y mide 130,5 × 190 cm. La obra se conserva en el Musée d’Orsay de París y se relaciona con [[edouard-manet|Édouard Manet]], el realismo, el desnudo, el cuerpo, el deseo, la sexualidad, el género y la mirada.' || chr(10) || chr(10) || 'Esas conexiones sitúan la obra en un punto de tensión: retoma un formato reconocible de la historia del arte, pero hace que la figura y su mirada interrumpan la distancia idealizada del desnudo tradicional.' WHERE id='cmsvvxihi00m785sje6zpfn92';
UPDATE "EntityTranslation" SET "shortDescription"='Olympia, pintada por Édouard Manet en 1863, es un óleo sobre lienzo relacionado con el cuerpo, el deseo, el desnudo, la mirada y el género.', essay='## Cuerpo y mirada' || chr(10) || chr(10) || '[[olympia|Olympia]] fue pintada en 1863 con óleo sobre lienzo y mide 130,5 × 190 cm. La obra se conserva en el Musée d’Orsay de París y se relaciona con [[edouard-manet|Édouard Manet]], el realismo, el desnudo, el cuerpo, el deseo, la sexualidad, el género y la mirada.' || chr(10) || chr(10) || 'Esas conexiones sitúan la obra en un punto de tensión: retoma un formato reconocible de la historia del arte, pero hace que la figura y su mirada interrumpan la distancia idealizada del desnudo tradicional.', excerpt='Olympia, pintada por Édouard Manet en 1863, es un óleo sobre lienzo relacionado con el cuerpo, el deseo, el desnudo, la mirada y el género.' WHERE "entityId"='cmsvvxihi00m785sje6zpfn92' AND locale='es';
UPDATE "EntityTranslation" SET "shortDescription"='Olympia, painted by Édouard Manet in 1863, is an oil painting on canvas connected with the body, desire, the nude, the gaze, and gender.', essay='## Body and gaze' || chr(10) || chr(10) || '[[olympia|Olympia]] was painted in 1863 in oil on canvas and measures 130.5 × 190 cm. It is held by the Musée d’Orsay in Paris and connected with [[edouard-manet|Édouard Manet]], realism, the nude, the body, desire, sexuality, gender, and the gaze.' || chr(10) || chr(10) || 'These connections place the work at a point of tension. It uses a recognizable format from art history, but makes the figure’s presence and gaze interrupt the idealized distance of the traditional nude.' , excerpt='Olympia, painted by Édouard Manet in 1863, is an oil painting on canvas connected with the body, desire, the nude, the gaze, and gender.' WHERE "entityId"='cmsvvxihi00m785sje6zpfn92' AND locale='en';

COMMIT;
